import { useEffect, useState } from "react";
import axios from "axios";

export default function WeatherHistory() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const getWeather = async () => {
      try {
        const res = await axios.get(
          "https://api.open-meteo.com/v1/forecast?latitude=34.68&longitude=-1.91&past_days=7&daily=temperature_2m_max,temperature_2m_min&timezone=Africa%2FCasablanca"
        );
        setData(res.data);
      } catch (err) {
        console.log("Error:", err);
      } finally {
        setLoading(false);
      }
    };

    getWeather();
  }, []);

  if (loading) return <p>Loading...</p>;

  return (
    <div style={{ color: "#fff" }}>
      <h2>Weather History (7 Days)</h2>

      {data?.daily?.time?.map((day, index) => (
        <div key={day}>
          <p>
            📅 {day} — Max: {data.daily.temperature_2m_max[index]}°C | Min:{" "}
            {data.daily.temperature_2m_min[index]}°C
          </p>
        </div>
      ))}
    </div>
  );
}
